contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // Precondition: array must be non-empty, otherwise transfer's own require reverts before any loop work
        require(_tos.length > 0);

        // Count how many recipients there are; this is purely a parameter-derived value
        uint len = _tos.length;

        // Make the deciding call. It may revert if any inner call fails; we capture that.
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
        }

        // General rule: the function never silently succeeds partially.
        // If it did not revert, it must have returned true.
        // If it did revert, we don't constrain the return value (it is not assigned).
        // This is expressed without reading any private storage of C.
        assert(reverted || ret);
    }

    receive() external payable {}
}

