    function run(address from, address caddress, address to, uint v) public payable {
        // Single recipient array, so the loop runs exactly once
        address[] memory _tos = new address[](1);
        _tos[0] = to;

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
        }

        // General rule over all inputs: either the call reverts, or it returns true.
        // It can never return false (vacuously: if it returned false, ret would be false and reverted false, violating the assert).
        assert(reverted || ret);
    }

    receive() external payable {}
}

